package cn.shiguang.qwenpocket;
import android.app.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.util.*;
final class CubePreview {
    final MainActivity a;final boolean[] grid;
    CubePreview(MainActivity a,boolean[] grid){this.a=a;this.grid=grid.clone();}
    void show(){int[][][] basis=CubeNet.fold(grid);LinearLayout page=a.column();page.addView(a.text("拖动旋转，标签对应展开图的（行,列）。",13,MainActivity.MUTED));View canvas=new View(a){float yaw=.6f,pitch=-.4f,lastX,lastY;Paint p=new Paint(3);
        float[] rotate(float[] v){float x=(float)(v[0]*Math.cos(yaw)+v[2]*Math.sin(yaw)),z=(float)(-v[0]*Math.sin(yaw)+v[2]*Math.cos(yaw));return new float[]{x,(float)(v[1]*Math.cos(pitch)-z*Math.sin(pitch)),(float)(v[1]*Math.sin(pitch)+z*Math.cos(pitch))};}
        protected void onDraw(Canvas c){ArrayList<float[]> faces=new ArrayList<>();for(int i=0;i<25;i++)if(basis[i]!=null){int[] n=basis[i][2];float[] v=rotate(new float[]{n[0],n[1],n[2]});faces.add(new float[]{i,v[2]});}faces.sort((x,y)->Float.compare(x[1],y[1]));float scale=Math.min(getWidth(),getHeight())*.25f;for(float[] f:faces){int id=(int)f[0];int[][] b=basis[id];Path path=new Path();float cx=0,cy=0;int[][] signs={{-1,-1},{1,-1},{1,1},{-1,1}};for(int k=0;k<4;k++){float[] v=new float[3];for(int j=0;j<3;j++)v[j]=b[2][j]+signs[k][0]*b[0][j]+signs[k][1]*b[1][j];v=rotate(v);float x=getWidth()/2f+v[0]*scale,y=getHeight()/2f+v[1]*scale;if(k==0)path.moveTo(x,y);else path.lineTo(x,y);cx+=x/4;cy+=y/4;}path.close();p.setStyle(Paint.Style.FILL);p.setColor(Color.HSVToColor(new float[]{(id*53)%360,.3f,.95f}));c.drawPath(path,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);p.setColor(MainActivity.INK);c.drawPath(path,p);p.setStyle(Paint.Style.FILL);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(a.dp(16));c.drawText(CubeNet.label(id),cx,cy,p);}}
        public boolean onTouchEvent(MotionEvent e){if(e.getAction()==MotionEvent.ACTION_MOVE){yaw+=(e.getX()-lastX)*.012f;pitch+=(e.getY()-lastY)*.012f;invalidate();}lastX=e.getX();lastY=e.getY();return true;}};page.addView(canvas,new LinearLayout.LayoutParams(-1,a.dp(290)));new AlertDialog.Builder(a).setTitle("折叠预览").setView(page).setPositiveButton("返回",null).show();}
}
